import Database from "better-sqlite3";
import path from "path";
import fs from "fs";

const DB_DIR = path.join(process.cwd(), ".data");
const DB_PATH = path.join(DB_DIR, "ollama-ui.db");

if (!fs.existsSync(DB_DIR)) {
  fs.mkdirSync(DB_DIR, { recursive: true });
}

let _db: Database.Database | null = null;

export function getDb(): Database.Database {
  if (_db) return _db;
  _db = new Database(DB_PATH);
  _db.pragma("journal_mode = WAL");
  _db.pragma("foreign_keys = ON");
  initSchema(_db);
  return _db;
}

function initSchema(db: Database.Database) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS sessions (
      id        TEXT PRIMARY KEY,
      title     TEXT NOT NULL DEFAULT 'New Chat',
      model     TEXT NOT NULL,
      system_prompt TEXT NOT NULL DEFAULT '',
      created_at INTEGER NOT NULL DEFAULT (unixepoch()),
      updated_at INTEGER NOT NULL DEFAULT (unixepoch())
    );

    CREATE TABLE IF NOT EXISTS messages (
      id         TEXT PRIMARY KEY,
      session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
      role       TEXT NOT NULL CHECK(role IN ('user','assistant','system')),
      content    TEXT NOT NULL,
      created_at INTEGER NOT NULL DEFAULT (unixepoch())
    );

    CREATE INDEX IF NOT EXISTS idx_messages_session ON messages(session_id, created_at);
  `);
}

// ── Sessions ──────────────────────────────────────────────────────────────────

export interface Session {
  id: string;
  title: string;
  model: string;
  system_prompt: string;
  created_at: number;
  updated_at: number;
}

export function listSessions(): Session[] {
  return getDb()
    .prepare("SELECT * FROM sessions ORDER BY updated_at DESC")
    .all() as Session[];
}

export function getSession(id: string): Session | undefined {
  return getDb()
    .prepare("SELECT * FROM sessions WHERE id = ?")
    .get(id) as Session | undefined;
}

export function createSession(
  id: string,
  model: string,
  title = "New Chat",
  system_prompt = ""
): Session {
  const db = getDb();
  db.prepare(
    `INSERT INTO sessions (id, title, model, system_prompt) VALUES (?, ?, ?, ?)`
  ).run(id, title, model, system_prompt);
  return getSession(id)!;
}

export function updateSession(
  id: string,
  fields: Partial<Pick<Session, "title" | "model" | "system_prompt">>
): Session | undefined {
  const db = getDb();
  const sets: string[] = [];
  const vals: unknown[] = [];
  if (fields.title !== undefined) {
    sets.push("title = ?");
    vals.push(fields.title);
  }
  if (fields.model !== undefined) {
    sets.push("model = ?");
    vals.push(fields.model);
  }
  if (fields.system_prompt !== undefined) {
    sets.push("system_prompt = ?");
    vals.push(fields.system_prompt);
  }
  if (sets.length === 0) return getSession(id);
  sets.push("updated_at = unixepoch()");
  vals.push(id);
  db.prepare(`UPDATE sessions SET ${sets.join(", ")} WHERE id = ?`).run(...vals);
  return getSession(id);
}

export function deleteSession(id: string) {
  getDb().prepare("DELETE FROM sessions WHERE id = ?").run(id);
}

// ── Messages ──────────────────────────────────────────────────────────────────

export interface Message {
  id: string;
  session_id: string;
  role: "user" | "assistant" | "system";
  content: string;
  created_at: number;
}

export function getMessages(session_id: string): Message[] {
  return getDb()
    .prepare(
      "SELECT * FROM messages WHERE session_id = ? ORDER BY created_at ASC"
    )
    .all(session_id) as Message[];
}

export function addMessage(
  id: string,
  session_id: string,
  role: Message["role"],
  content: string
): Message {
  const db = getDb();
  db.prepare(
    `INSERT INTO messages (id, session_id, role, content) VALUES (?, ?, ?, ?)`
  ).run(id, session_id, role, content);
  // bump session updated_at
  db.prepare(`UPDATE sessions SET updated_at = unixepoch() WHERE id = ?`).run(
    session_id
  );
  return db
    .prepare("SELECT * FROM messages WHERE id = ?")
    .get(id) as Message;
}

export function deleteMessage(id: string) {
  getDb().prepare("DELETE FROM messages WHERE id = ?").run(id);
}

export function clearMessages(session_id: string) {
  getDb()
    .prepare("DELETE FROM messages WHERE session_id = ?")
    .run(session_id);
}
